const payload = $json.body || $json;
const text = (payload.text || '').trim();
return [{
  json: {
    text,
    response_url: payload.response_url,
    user_id: payload.user_id,
    user_name: payload.user_name
  }
}];

/* app_mention イベント形式:
{
  body: {
    event: {
      type: 'app_mention',
      user: 'U123',
      text: '<@Ubot> @trans これ訳して',
      channel: 'C123',
      ts: '173+1234567890',
      thread_ts: '173+1234567890' (optional)
    }
  }
}
*/

const body = $json.body || $json;
const ev = body.event || {};

let raw = ev.text || '';
// <@U...> とか @trans を除去
raw = raw.replace(/<@[^>]+>/g, '').replace(/@trans/gi, '').trim();

const thread_ts = ev.thread_ts || ev.ts;

return [{
  json: {
    textToTranslate: raw,
    channel: ev.channel,
    thread_ts,
    user_id: ev.user
  }
}];

/*
  Slack reaction_added payload 例:
  {
    "event": {
      "type": "reaction_added",
      "user": "U123456",
      "reaction": "jp",
      "item": {
        "type": "message",
        "channel": "C123456",
        "ts": "173+1234567890"
      }
    }
  }
*/

let body = $json;

// n8nのWebhookノードでは payload が body 下に入る場合と、直下に入る場合がある
if ($json.body && typeof $json.body === 'object') {
  body = $json.body;
}

const ev = body.event || {};

// デバッグ用ログ（必要なら一時的にON）
console.log('reaction event', ev);

return [
  {
    json: {
      reactor_user: ev.user || null,
      reaction: ev.reaction || null,
      channel: ev.item?.channel || null,
      message_ts: ev.item?.ts || null,
      raw: ev
    }
  }
];

const eventCtx = $node['Parse Reaction Event'].json;
const apiRes = $json;

if (!apiRes.ok || !apiRes.messages || !apiRes.messages.length) {
  return [{ json: { skip: true, reason: 'no message found' } }];
}

const msg = apiRes.messages[0];
const textToTranslate = msg.text || '';
const thread_ts = msg.thread_ts || msg.ts;
const channel = eventCtx.channel;

return [{
  json: {
    textToTranslate,
    channel,
    thread_ts
  }
}];

/* /trans 用フォーマッタ
   出力イメージ:
   【from @後藤】\n(日本語原文...)\n----------\n(英語訳...)
*/
const ctx = $node['Parse Slash Payload'].json;
const llm = $json;

let output = llm.text || llm.output || '';

// [Original] と [Translation] を分離
let original = '';
let translation = '';
const match = output.match(/\[Original\]([\s\S]*?)\[Translation\]([\s\S]*)/i);
if (match) {
  original = match[1].trim();
  translation = match[2].trim();
} else {
  translation = output.trim();
}

const fromUser = ctx.user_id ? `<@${ctx.user_id}>` : (ctx.user_name || 'someone');
const finalMessage = `【from ${fromUser}】\n${original}\n----------\n${translation}`;

return [{
  json: {
    response_url: ctx.response_url,
    message: finalMessage
  }
}];

/* @trans 用フォーマッタ
   訳文だけ返す（スレッド）
*/
const ctx = $node['Parse Mention Event'].json;
const llm = $json;

let output = llm.text || llm.output || '';
output = output
  .replace(/\[Original\][\s\S]*?\[Translation\]/i, '')
  .replace(/\[Translation\]/i, '')
  .trim();

return [{
  json: {
    channel: ctx.channel,
    thread_ts: String(ctx.thread_ts),
    text: output
  }
}];

/* reaction 用フォーマッタ
   訳文だけ返す（スレッド）
*/
const ctx = $node['Prep Reaction Translation Input'].json;
const llm = $json;

let output = llm.text || llm.output || '';
output = output
  .replace(/\[Original\][\s\S]*?\[Translation\]/i, '')
  .replace(/\[Translation\]/i, '')
  .trim();

return [{
  json: {
    channel: ctx.channel,
    thread_ts: String(ctx.thread_ts),
    text: output
  }
}];

/*
  :jp: / :jp-flag: / :flag-jp: / :us: / :flag-us: などに対応
  → それ以外のリアクションはスキップ
*/

const allowedPatterns = ['jp', 'us'];
const reaction = ($json.reaction || '').toLowerCase();

// 部分一致チェック
const isAllowed = allowedPatterns.some(p => reaction.includes(p));

if (!isAllowed) {
  return [{ json: { skip: true, reason: `irrelevant reaction: ${reaction}` } }];
}

return [{ json: $json }];
